    """Wrap text to fit terminal width with proper indentation."""
    if width is None:
        width, _ = DisplayManager.get_terminal_size()
    effective_width = width - indent
    paragraphs = [p.strip() for p in text.strip().split('\n\n')]
    wrapped_paragraphs = []
    for paragraph in paragraphs:
        paragraph = ' '.join(paragraph.split())
        wrapped = textwrap.fill(paragraph, width=effective_width, expand_tabs=True, replace_whitespace=True, break_long_words=False, break_on_hyphens=True, initial_indent=' ' * indent, subsequent_indent=' ' * indent)
